class Task:
    def __init__(self, C, D, alpha_function):
        self.C = C  # Worst-Case Execution Time
        self.D = D  # Relative Deadline
        self.alpha = alpha_function  # Arrival-Bound Function

class Job:
    def __init__(self, task_id, arrival_time, actual_cost):
        self.task_id = task_id
        self.a = arrival_time
        self.c = actual_cost
        self.d = self.a + task_set[task_id].D # Absolute Deadline
        # Constraint: 0 <= self.c <= task_set[task_id].C

def check_arrival_bound(task_i, arrival_sequence, t, delta):
    job_count = 0
    for job in arrival_sequence:
        if job.task_id == task_i.id and t <= job.a < t + delta:
            job_count += 1
    return job_count <= task_i.alpha(delta)

def is_job_cost_valid(job, task_set):
    task_i = task_set[job.task_id]
    return job.c <= task_i.C

class ProcessorState:
    IDLE = 'None'
    def __init__(self, job=None):
        self.job = job

class Schedule:
    def __init__(self):
        self.timeline = {}

    def get_state_at(self, t):
        return self.timeline.get(t, ProcessorState.IDLE)

def is_scheduled(job, t, sched):
    state = sched.get_state_at(t)
    return state.job == job

def calculate_service(job, t, sched):
    service_received = 0
    for t_prime in range(t):
        if is_scheduled(job, t_prime, sched):
            service_received += 1
    return service_received

def is_complete(job, t, sched):
    return calculate_service(job, t, sched) >= job.c

def is_work_conserving(schedule, arrival_sequence, all_jobs):
    for t in range(MAX_TIME):
        pending_jobs = []
        for job in all_jobs:
            if job.a <= t and not is_complete(job, t, schedule):
                pending_jobs.append(job)

        if len(pending_jobs) > 0:
            # If there are pending jobs, the processor must be busy
            if schedule.get_state_at(t).job is None:
                return False # Processor is idle but jobs are pending
    return True

def is_priority_inverted(j, t, sched):
    for j_lp in all_jobs:
        # Check if j has higher-or-equal priority than j_lp
        # (meaning j arrived no later than j_lp, and they are different jobs)
        if j.id != j_lp.id and j.a <= j_lp.a:
            if is_scheduled(j_lp, t, sched):
                return True
    return False

def calculate_int_wl_hep_jobs(j, t, arrival_sequence):
    total_workload = 0
    jobs_arriving_at_t = arrival_sequence.get_jobs_at(t) # Assume this function exists
    for j_hp in jobs_arriving_at_t:
        if is_higher_or_equal_priority(j_hp, j):
            total_workload += j_hp.c
    return total_workload

def is_interfered(j, t, schedule):
    if is_priority_inverted(j, t, schedule):
        return True

    for j_hp in all_jobs:
        if is_higher_or_equal_priority(j_hp, j) and is_scheduled(j_hp, t, schedule):
            return True
    return False

def calculate_IBF(A, task_i, task_set):
    total_workload_in_window = 0
    for task_k in task_set:
        total_workload_in_window += calculate_RBF(task_k, A + 1) # epsilon = 1
    return total_workload_in_window - task_i.C

def calculate_A_set(L, task_set):
    A_set = set()
    # Iterate through possible A values up to L
    for A in range(L):
        for task_k in task_set:
            # Check for 'step' in RBF_k
            if calculate_RBF(task_k, A) != calculate_RBF(task_k, A + 1):
                A_set.add(A)
                break # Found a step for this A, move to next A
    return sorted(list(A_set))

def calculate_response_time_bound(A_set, task_set):
    R = 0
    for A in A_set:
        total_workload_in_window = 0
        for task_k in task_set:
            total_workload_in_window += calculate_RBF(task_k, A + 1) # epsilon = 1

        current_F = total_workload_in_window - A
        R = max(R, current_F)
    return R

def prove_abstract_in_concrete(A):
    # Assume is_in_abstract_search_space(A) is true
    # This lemma's proof would show that this implies:
    # A < L and (exists task_k, calculate_RBF(task_k, A) != calculate_RBF(task_k, A + 1))
    # which is the definition of is_in_concrete_search_space(A)
    return is_in_concrete_search_space(A)
